    Cursor c = null;
    SQLiteDatabase db = this.mHelper.getReadableDatabase();
    switch (mMatcher.match(uri)) {
        case 1:
            c = db.query(NotesDatabaseHelper.TABLE.NOTE, projection, selection, selectionArgs, null, null, sortOrder);
            break;
