            c = db.query(NotesDatabaseHelper.TABLE.NOTE, projection, "_id=" + id + parseSelection(selection), selectionArgs, null, null, sortOrder);
            break;
        case 3:
            c = db.query(NotesDatabaseHelper.TABLE.DATA, projection, selection, selectionArgs, null, null, sortOrder);
            break;
