        case 6:
            if (sortOrder != null || projection != null) {
                throw new IllegalArgumentException("do not specify sortOrder, selection, selectionArgs, or projectionwith this query");
            }
            if (mMatcher.match(uri) == 6) {
                if (uri.getPathSegments().size() <= 1) {
                    searchString = null;
                } else {
                    String searchString2 = uri.getPathSegments().get(1);
                    searchString = searchString2;
                }
            } else {
                String searchString3 = uri.getQueryParameter("pattern");
                searchString = searchString3;
            }
            if (TextUtils.isEmpty(searchString)) {
                return null;
            }
            try {
                c = db.rawQuery(NOTES_SNIPPET_SEARCH_QUERY, new String[]{String.format("%%%s%%", searchString)});
            } catch (IllegalStateException ex) {
                Log.e(TAG, "got exception: " + ex.toString());
            }
            break;
            break;
        default:
            throw new IllegalArgumentException("Unknown URI " + uri);
    }
    if (c != null) {
        c.setNotificationUri(getContext().getContentResolver(), uri);
    }
    return c;
}
